S=/tmp/claude-0/-home-user-EdFringeNow/47726ac1-6d37-59b9-b4ee-08586ef09cb8/scratchpad && cat > "$S/live.mjs" <<'EOF'
// Drives the LIVE site. Headless Chromium cannot tunnel the sandbox proxy to an
// external host, so every request is fulfilled by curl, which can.
import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';
import { execFileSync } from 'node:child_process';
import { readFileSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const TYPES = { '.html': 'text/html', '.css': 'text/css', '.js': 'text/javascript',
                '.json': 'application/json', '.svg': 'image/svg+xml', '.png': 'image/png' };
const dir = mkdtempSync(join(tmpdir(), 'live-'));
let n = 0;

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1200, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));

await page.route('**/*', (route) => {
  const url = new URL(route.request().url());
  if (url.hostname !== 'edfringenow.com') return route.fulfill({ status: 204, body: '' });
  const out = join(dir, `f${n++}`);
  try {
    execFileSync('curl', ['-sS', '--max-time', '60', '-o', out, url.href], { stdio: 'pipe' });
  } catch { return route.abort(); }
  const ext = Object.keys(TYPES).find((e) => url.pathname.endsWith(e));
  return route.fulfill({ body: readFileSync(out), contentType: TYPES[ext] || 'text/html' });
});

await page.goto('https://edfringenow.com/', { waitUntil: 'domcontentloaded' });
await page.waitForTimeout(6000);
const foot = await page.$('#footerVersion');
if (foot) { await foot.click(); await page.waitForTimeout(500); }
const shown = await page.evaluate(() => [...document.querySelectorAll('body *')]
  .filter((e) => !e.children.length && /v\d+\.\d+\.\d+/.test(e.textContent || ''))
  .map((e) => e.textContent.trim()));
console.log('versions rendered on the live page:', JSON.stringify([...new Set(shown)]));
console.log(errors.length ? `PAGE ERRORS: ${errors.join('; ')}` : 'no page errors');
await page.screenshot({ path: `${dir}/live.png` });
console.log('shot:', `${dir}/live.png`);
await browser.close();
EOF
node "$S/live.mjs"

