{
  // What Cloudflare serves, and from where. The cloudflare-site pack's
  // site-release task reads this file to learn both, and its checks hold the
  // two answers honest.
  "$schema": "./node_modules/wrangler/config-schema.json",
  "name": "edfringenow",

  // Pinned, so the runtime a release lands on is a value in the repo rather
  // than whatever the deploy day defaults to. Moving it is a deliberate commit.
  "compatibility_date": "2026-09-16",

  // There is no Worker script: this is a static site, so the whole deployment
  // is the asset tree and `main` is deliberately absent.
  "assets": {
    // The ONE published directory, and the whole upload. A file outside it is
    // absent from the live site with no error anywhere — which is why the repo
    // keeps the scraper, the pipeline's working data, the vendored mount and
    // the queue workers outside it rather than excluding them by name.
    "directory": "./site",

    // The default, stated: `/plan/` resolves to plan/index.html with the
    // trailing slash, and `/privacy.html` is served without one. Both are the
    // URLs the site already had on Pages, so spelling it out is what keeps a
    // future change to this key a visible decision.
    "html_handling": "auto-trailing-slash",

    // Serve site/404.html for a path that matches no asset. Without this the
    // default is a bare, body-less 404 — a regression against Pages, which
    // served a real page. NOT "single-page-application": this site is four
    // separate pages plus three planners, and answering every unknown path
    // with index.html would serve the Now page under any URL a visitor mistyped.
    "not_found_handling": "404-page"
  },

  // The hostnames a visitor types. Cloudflare writes the DNS record for each as
  // the deploy attaches it, so nothing here needs a record created by hand —
  // but a record the PREVIOUS host left on one of these names blocks the
  // attach, which the release's preflight resolves and parks on before it
  // consumes a version number.
  "routes": [
    { "pattern": "edfringenow.com", "custom_domain": true },
    { "pattern": "www.edfringenow.com", "custom_domain": true }
  ],

  // Off, because it defaults to ON and would publish this same site a second
  // time at edfringenow.<account>.workers.dev — a public URL nobody chose,
  // serving the same pages from a name that is not the product's. Disabling it
  // also disables preview URLs, which take their default from this key.
  "workers_dev": false
}

