# What sits inside the published tree but is not part of the served product.
# assets.directory uploads everything under site/, so this file — not a list
# kept somewhere else — is what holds these back. Gitignore syntax: wrangler
# matches with the `ignore` package, and a pattern with no slash matches at any
# depth while one containing a slash is anchored to site/.
#
# The tests live beside the code they test, which is where they belong; they are
# simply not pages. The Pages publish set shipped them — it named code
# directories wholesale and could not exclude a subdirectory — so dropping them
# here makes the live site smaller than it was rather than larger.
__tests__/

# The planner's static design mock and its notes: a prototype, never part of the
# product. The Pages publish set enumerated plan/ file by file to keep this out;
# this line is what replaces that enumeration.
plan/design/

# Documentation and tooling that happen to live next to the code they belong to.
plan/README.md
plan/package.json
EOF
S=/tmp/claude-0/-home-user-EdFringeNow/47726ac1-6d37-59b9-b4ee-08586ef09cb8/scratchpad
node --input-type=module -e "
import ignore from '/root/.npm/_npx/2230cd9b5abd26ce/node_modules/ignore/index.js';
import { readFileSync } from 'node:fs';
import { execSync } from 'node:child_process';
// wrangler's own defaults, from CF_ASSETS_IGNORE_FILENAME / REDIRECTS / HEADERS
const patterns = ['/.assetsignore', '/_redirects', '/_headers',
  ...readFileSync('site/.assetsignore','utf8').split('\n')];
const ig = ignore.default ? ignore.default().add(patterns) : ignore().add(patterns);
const files = execSync('find site -type f', {encoding:'utf8'}).trim().split('\n')
  .map(f => f.replace(/^site\//,''));
const dropped = files.filter(f => ig.test(f).ignored).sort();
const kept = files.filter(f => !ig.test(f).ignored);
console.log('total files under site/:', files.length);
console.log('EXCLUDED (' + dropped.length + '):'); dropped.forEach(f => console.log('  - ' + f));
console.log('UPLOADED:', kept.length);
console.log('sanity — these must be UPLOADED:');
for (const f of ['index.html','plan/index.html','js/app.js','shared/price.js','data/venues.json','data/days/2026-08-15.json','404.html'])
  console.log('  ', ig.test(f).ignored ? 'DROPPED ✗' : 'kept ✓', f);
"

