    }
  } catch (err) {
    console.warn("Fringe Planner: couldn't read app version", err);
  }
  renderPerfPill();
}

/** Fold one reschedule (buildSchedule) duration into the rolling stats. */
function recordResched(ms) {
  const p = state.perf;
  p.count++;
  p.sum += ms;
