1	// Shared recipe pieces for screen/behavior cases: storage seeds, readiness
2	// waits and common drives — so a case stays a few declarative lines and the
3	// judgement about "when is the page settled" is made once, here.
4	"use strict";
5	
6	const path = require("node:path");
7	const fs = require("node:fs");
8	const { REFERENCE_NOW_UTC_MS } = require("./reference-now");
9	
10	const FIXTURES_DIR = path.join(__dirname, "fixtures");
11	
12	// ------------------------------------------------------------ storage seeds --
13	// Now page: the intro is dismissed for every case except the intro's own.
14	function nowStorage(extra = {}) {
15	  return {
16	    "edfringenow.now.intro.v1": JSON.stringify({ dismissed: true }),
17	    ...extra,
18	  };
19	}
20	
21	// Now page settings snapshot (filters, plan). Merged over the app's defaults.
22	function nowSettings(overrides = {}) {
23	  return {
24	    "edfringenow.now.v1": JSON.stringify({ date: "2026-08-15", ...overrides }),
25	  };
26	}
27	
28	// Planner: a stored favourites list (fresh at the reference moment, so the
29	// 3-day TTL is live) and stored preferences.
30	const PLAN_FAVOURITES = [
31	  "100-full-blown-redacted",
32	  "116-grams-a-play-to-lose-weight",
33	  "15-minutes-of-shame",
34	  "borderlandscomedy",
35	  "anyone-fancy-a-bagel",
36	  "100-million-fish-in-the-aquarium",
37	  "100-scouse-comedy",
38	  "4-better-or-4-worse",
39	  "ray-bradshaw-five-years-in-a-row",
40	];
41	
42	function planFavourites(slugs = PLAN_FAVOURITES) {
43	  return {
44	    "edfringe.plan.favourites.v1": JSON.stringify({
45	      v: 1,
46	      slugs,
47	      filename: "favourites.csv",
48	      savedAt: REFERENCE_NOW_UTC_MS,
49	    }),
50	  };
51	}
52	
53	function planPrefs(overrides = {}) {
54	  return { "edfringe.plan.prefs.v1": JSON.stringify(overrides) };
55	}
56	
57	// Festival planner (/planJerusalem): a starred list, under that page's own
58	// storage prefix. The cast spans what Part V asserts — a free late-night that
59	// repeats on four evenings, two runs that play twice in one evening, a film,
60	// two shows half an hour apart at different venues (so the schedule draws a
61	// travel leg), and a clash that cannot be fitted (so the grid shows a verdict
62	// other than "Scheduled").
63	const JERUSALEM_STARRED = [
64	  "opening",
65	  "poetry-slam",
66	  "salakh",
67	  "late",
68	  "king",
69	  "yona-kapach",
70	  "neighbor",
71	];
72	
73	function jerusalemStarred(slugs = JERUSALEM_STARRED) {
74	  return { "jerusalemPlan.starred": JSON.stringify(slugs) };
75	}
76	
77	// ------------------------------------------------------------------- waits --
78	async function settle(page) {
79	  await page.evaluate(() => document.fonts.ready);
80	  await page.waitForTimeout(250);
81	}
82	
83	// Now page is ready once the list (or its empty-state note) has rendered, the
84	// async version fetch has landed in the footer tooltip, and the fixed-clock
85	// reference day has taken over from the app's built-in simulated one.
86	async function nowReady(page) {
87	  await page.waitForSelector("#showsGrid .show-item, #showsGrid .show-meta", { timeout: 20000 });
88	  // The version lands in the footer's popup element (shared/version-popup.js),
89	  // which is the signal that the page's own scripts have run — the number comes
90	  // from the page's stamp, pinned by the harness.
91	  await page.waitForFunction(() => {
92	    const pop = document.querySelector("#footerVersion .version-pop");
93	    return pop && pop.textContent.includes("v0.0.0-spec");
94	  }, { timeout: 20000 });
95	  // The app boots on its built-in simulated day and only adopts the (fixed)
96	  // real clock once the in-UK geolocation fix lands — wait for the reference
97	  // day to actually be in force, or a slow fix leaves the preset day rendered.
98	  await page.waitForFunction(() => {
99	    const l = document.getElementById("constraintDateLabel");
100	    return l && l.textContent.includes("15 Aug");
101	  }, { timeout: 20000 });
102	  await settle(page);
103	}
104	
105	// The postcard planner (/plan2): the page marks itself ready once the test
106	// data and the symbol sheet are in and the first render has landed.
107	async function plan2Ready(page) {
108	  await page.waitForSelector("body[data-ready]", { timeout: 20000 });
109	  await settle(page);
110	}
111	
112	// Planner is ready when the catalogue has landed (the search placeholder
113	// switches to the real count) and the version tooltip is in.
114	async function planReady(page) {
115	  await page.waitForFunction(() => {
116	    const i = document.getElementById("ssInput");
117	    return i && i.placeholder.startsWith("Search all");
118	  }, { timeout: 20000 });
119	  // Same version-tooltip wait as nowReady, above.
120	  await page.waitForFunction(() => {
121	    const pop = document.querySelector("#footerVersion .version-pop");
122	    return pop && pop.textContent.includes("v0.0.0-spec");
123	  }, { timeout: 20000 });
124	  await settle(page);
125	}
126	
127	// The festival planner is ready once the programme has landed (the board has
128	// either its browse list or its lanes) and the page's scripts have put the
129	// version in the footer popup.
130	async function jerusalemReady(page) {
131	  // `attached`, not `visible`: the browse list and the grid are the board's two
132	  // states and exactly one of them is on screen, so a visibility wait on both
133	  // can only ever resolve against the hidden one.
134	  await page.waitForSelector("#browseList .ss-row, #lanes .lane", { state: "attached", timeout: 20000 });
135	  await page.waitForFunction(() => {
136	    const pop = document.querySelector("#footerVersion .version-pop");
137	    return pop && pop.textContent.includes("v0.0.0-spec");
138	  }, { timeout: 20000 });
139	  // With shows on the board, the date-window overlay is positioned from the
140	  // laid-out day header two frames after the first render; capturing before
141	  // that catches every piece of it at zero width. An empty board has no
142	  // overlay to wait for.
143	  await page.waitForFunction(() => {
144	    if (!document.querySelector("#lanes .lane")) return true;
145	    const band = document.getElementById("railBand");
146	    return band && band.style.width !== "";
147	  }, { timeout: 20000 });
148	  await settle(page);
